    const head=n(a.headSize,0.3,0.1,0.8),tail=n(a.tailLength,0.35,0,1.4),limbs=Math.max(0,Math.round(n(a.limbCount,morphology.limbCount===undefined?4:morphology.limbCount,0,8)));
